def rule(ctx):
    t = ctx.t
    T = ctx.T if ctx.T and ctx.T > 0 else 1.0
    remaining = ctx.remaining
    if remaining is None:
        remaining = T - t
    if remaining < 0:
        remaining = 0.0

    robots = ctx.robots
    n = len(robots)

    def params(k):
        if k is not None and 0 <= k < len(ctx.types) and ctx.types[k] is not None:
            return ctx.types[k]
        return None

    type_count = {}
    for r in robots:
        type_count[r.type] = type_count.get(r.type, 0) + 1

    target_work = None
    if type_count:
        best_t = None
        best_c = -1
        for k in type_count:
            c = type_count[k]
            if c > best_c or (c == best_c and (best_t is None or k < best_t)):
                best_c = c
                best_t = k
        p = params(best_t)
        if p is not None:
            target_work = p.get("work_time", 10.0) or 10.0

    if target_work is None:
        p = params(ctx.gene_type)
        if p is not None:
            target_work = p.get("work_time", 10.0) or 10.0
        else:
            target_work = 10.0

    def fair_key(r):
        p = params(r.type)
        if p is None:
            work = 10.0
            cont = 1.0
            budget = r.budget if r.budget is not None else cont
        else:
            work = p.get("work_time", 10.0) or 10.0
            cont = p.get("continue_max_work", 1.0) or 1.0
            budget = r.budget if r.budget is not None else cont

        if work <= 0:
            work = 10.0
        if cont <= 0:
            cont = 1.0

        used = (cont - budget) / cont
        if used < 0:
            used = 0.0
        if used > 1:
            used = 1.0

        hour_units = r.hours / 10.0
        index = 0.55 * r.count + 0.30 * hour_units + 0.15 * used

        ready = r.ready if r.ready is not None else t
        wait = t - ready
        if wait < 0:
            wait = 0.0
        index = index - 0.0001 * wait

        dl = r.duties_left if r.duties_left is not None else 0
        return (index, r.count, r.hours, -dl, r.idx)

    def alt_key(r):
        p = params(r.type)
        if p is None:
            cont = 1.0
            budget = r.budget if r.budget is not None else cont
        else:
            cont = p.get("continue_max_work", 1.0) or 1.0
            budget = r.budget if r.budget is not None else cont

        if cont <= 0:
            cont = 1.0

        used = (cont - budget) / cont
        if used < 0:
            used = 0.0
        if used > 1:
            used = 1.0

        dl = r.duties_left if r.duties_left is not None else 1
        red = 1 if dl <= 1 else 0
        return (-red, -used, r.count, -dl, r.idx)

    actions = []

    if ctx.available:
        ordered = sorted(ctx.available, key=fair_key)
