            if idle < 0.0:
                idle = 0.0
            if ctx.T > 0:
                idle = idle / ctx.T
        dl = r.duties_left if r.duties_left is not None else 0
        score = -(2.0 * count_need + 0.8 * hours_need + 0.7 * maint_need + 0.15 * idle)
        score += 0.03 * dl
        return (score, r.count, r.hours, -r.budget, r.idx)

    def type_key(k):
        t = ctx.types[k]
        work = param(t, 'work_time', 1.0)
        if work <= 0:
