        if cycle <= 0:
            cycle = 1.0
        time_no_maint = duties * cycle
        if ctx.remaining <= time_no_maint:
            events = 0
        else:
            block = time_no_maint + maint
            if block <= 0:
                block = 1.0
            q = ctx.remaining / block
            events = int(q)
            if events < q:
                events += 1
            if events < 1:
                events = 1
        throughput = duties * work
        return (events, -throughput, maint, cycle, k)

    actions = [("reuse", r) for r in sorted(ctx.available, key=reuse_key)]

    candidates = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            candidates.append(k)

    new_types = []
    gt = ctx.gene_type
    if gt is not None and 0 <= gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
        new_types.append(gt)
