def rule(ctx):
    def type_info(k):
        t = ctx.types[k]
        work = t['work_time']
        single = t['single_work_time'] if t['single_work_time'] > 0 else work
        maxw = t['continue_max_work']
        duties = maxw / single if single > 0 else 1.0
        if duties < 1.0:
            duties = 1.0
        cycle = work + t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        if cycle <= 0:
            cycle = 1.0
        cap = duties * work
        total = duties * cycle + t['maintenance_time']
        if total <= 0:
            throughput = 0.0
        else:
            throughput = cap / total
        return throughput, cap, duties, work, t['maintenance_time'], t['charge_time']

    def reuse_key(r):
        return (
            r.hours,
            r.count,
            r.first_maint is not None,
            -r.duties_left,
            r.idx
        )

    ordered = sorted(ctx.available, key=reuse_key)
    actions = [("reuse", r) for r in ordered]

    candidates = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]
    gt = ctx.gene_type
    new_types = []
    if gt in candidates:
        new_types.append(gt)
        candidates.remove(gt)

    def new_key(k):
        throughput, cap, duties, work, maint, charge = type_info(k)
        fit = abs(work - min(ctx.remaining, work)) if ctx.remaining > 0 else 0
        return (-throughput, -cap, maint, charge, fit, k)

    candidates.sort(key=new_key)
    new_types.extend(candidates)
    for k in new_types:
        actions.append(("new", k))

    if not actions:
        actions.append(("new", gt))
    return actions
