def rule(ctx):
    def g(t, name, default):
        if t is None:
            return default
        v = t.get(name, default)
        return default if v is None else v

    remaining = ctx.remaining
    if remaining is None:
        remaining = 0.0
    if remaining < 0:
        remaining = 0.0

    cap = ctx.capacity
    if cap is None:
        cap = remaining
    slack = cap - remaining
    if remaining > 0:
        slack_ratio = slack / remaining
    else:
        slack_ratio = 1.0
    if slack_ratio < 0:
        slack_ratio = 0.0
    tight = slack_ratio <= 0.15

    robots = ctx.robots
    n = len(robots)
    if n > 0:
        total_count = 0
        total_hours = 0.0
        for r in robots:
            total_count += r.count
            total_hours += r.hours
        avg_count = total_count / n
        avg_hours = total_hours / n
    else:
        avg_count = 0.0
        avg_hours = 0.0

    def robot_score(r):
        t = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
        single = g(t, 'single_work_time', 1.0)
        if single <= 0:
            single = 1.0
        dl = r.duties_left
        if dl is None:
            if r.budget is not None:
                dl = int(r.budget / single)
            else:
                dl = 1
        if dl < 1:
            dl = 1

        count_dev = r.count - avg_count
        hours_dev = (r.hours - avg_hours) / max(1.0, single * 5.0)

        if r.last_end is not None:
            idle = ctx.t - r.last_end
            if idle < 0:
