        idle_term = -min(idle, 48.0) / 48.0

        if tight:
            maint_term = -dl * 0.7
        else:
            maint_term = dl * 0.25

        return 2.0 * count_dev + 0.8 * hours_dev + maint_term + 0.1 * idle_term

